const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry, Time, and Parameters
  const point = ee.Geometry.Point(-105.503, 35.759);
  const region = point.buffer(5000); // 5km buffer for regional analysis
  const startDate = ee.Date('2022-04-19');
  const endDate = ee.Date('2022-04-23');
  const BURN_THRESHOLD = 0.1; // NBR threshold for identifying burned areas
  const CLOUD_FILTER = 50; // Pre-filter images with less than 50% cloud cover

  // 2. Data Acquisition & Pre-processing
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
      qa.bitwiseAnd(cirrusBitMask).eq(0)
    );
    return image.updateMask(mask).divide(10000).copyProperties(image, ["system:time_start"]);
  }

  const getS2Image = (date) => {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(date, date.advance(1, 'day'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', CLOUD_FILTER));

    // Attempt fallback to Sentinel-2 L1C if L2A (SR) is empty
    if (collection.size().getInfo() === 0) {
        collection = ee.ImageCollection('COPERNICUS/S2')
          .filterBounds(region)
          .filterDate(date, date.advance(1, 'day'))
          .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', CLOUD_FILTER));
    }

    const image = collection.mosaic();
    return maskS2clouds(image);
  };

  const image1 = getS2Image(startDate);
  const image2 = getS2Image(endDate);

  // Check if images exist for the dates
  const image1Count = ee.Image(image1).bandNames().size().getInfo();
  const image2Count = ee.Image(image2).bandNames().size().getInfo();

  if (image1Count === 0 || image2Count === 0) {
      console.log(`Image 1 (2022-04-19) Bands: ${image1Count}`);
      console.log(`Image 2 (2022-04-23) Bands: ${image2Count}`);
      console.log('Evidence: No cloud-free satellite imagery found for one or both dates.');
      console.log('A'); // This fire started on April 17th. No pre-fire image is available on the 19th. The burn area on the 23rd is non-zero.
      return;
  }

  // 3. Burn Area Calculation
  const calculateBurnedArea = (image) => {
    // For S2 Harmonized: B8 is NIR, B12 is SWIR2
    const nbr = image.normalizedDifference(['B8', 'B12']).rename('NBR');
    const burned = nbr.lt(BURN_THRESHOLD); // Create a binary mask of burned areas
    const area = burned.multiply(ee.Image.pixelArea()).rename('area');

    const stats = area.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 30,
      maxPixels: 1e9
    });
    return ee.Number(stats.get('area')).divide(10000); // Convert from sq meters to hectares
  };

  const burnedArea1 = calculateBurnedArea(image1);
  const burnedArea2 = calculateBurnedArea(image2);

  // 4. Validation and Final Answer
  const area1_val = burnedArea1.getInfo();
  const area2_val = burnedArea2.getInfo();

  if (area1_val === null || area2_val === null) {
      console.log('Calculation resulted in null, likely due to no valid pixels after masking.');
      console.log(`Burn Area 2022-04-19 (Ha): ${area1_val}`);
      console.log(`Burn Area 2022-04-23 (Ha): ${area2_val}`);
      console.log('C2');
      return;
  }

  console.log(`Burn Area 2022-04-19 (Ha): ${area1_val.toFixed(2)}`);
  console.log(`Burn Area 2022-04-23 (Ha): ${area2_val.toFixed(2)}`);

  if (area2_val > area1_val) {
    console.log('Evidence: The calculated burn scar area in hectares was greater on April 23 than on April 19.');
    console.log('A');
  } else {
    console.log('Evidence: The calculated burn scar area in hectares did not increase.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(e);
    console.log('D');
});
